import { writeFile } from 'node:fs/promises';
import { join, resolve } from 'node:path';
import { performance } from 'node:perf_hooks';
import assert from 'node:assert/strict';
import { createDeterministicRepository, repositorySemanticSnapshot } from '../../packages/gitlode/test/support/deterministic-repository.ts';
const root = process.argv[2];
const start = performance.now();
const rows = [];
const operations = [];
const owner = {
  signal: new AbortController().signal, check() {}, root() {}, diagnostic(error) { throw error; },
  async work(operation) {
    const start = performance.now();
    try { return await operation(); }
    finally { operations.push(performance.now() - start); }
  },
  child(child) {
    const row = { pid: child.pid, args: child.spawnargs, startMs: performance.now() - start, stdoutBytes: 0, stderrBytes: 0 };
    rows.push(row);
    for (const stream of ['stdout', 'stderr']) child[stream]?.on('data', chunk => { row[stream + 'Bytes'] += chunk.length; });
    child.once('close', (code, signal) => Object.assign(row, { code, signal, closeMs: performance.now() - start }));
  },
};
try {
  const first = await createDeterministicRepository(join(root, 'first repository'), owner);
  const second = await createDeterministicRepository(join(root, 'second repository'), owner);
  assert.deepEqual(await repositorySemanticSnapshot(first, owner), await repositorySemanticSnapshot(second, owner));
  assert.equal(rows.length, 82);
  assert.equal(first.graph.length, 5);
  assert.equal(first.annotatedTagType, 'tag');
  assert.equal(first.lightweightTagType, 'commit');
  assert.equal(first.refs.main, first.refs.overlap);
  assert.ok(rows.every(row => row.code === 0 && row.closeMs !== undefined));
  await writeFile(join(root, 'workload.json'), JSON.stringify({ root: resolve(root), node: process.version, execPath: process.execPath, elapsedMs: performance.now()-start, rows, operationDurationsMs: operations, completed: true }, null, 2));
} catch (error) {
  await writeFile(join(root, 'workload.json'), JSON.stringify({ elapsedMs: performance.now()-start, rows, completed: false, error: String(error) }, null, 2));
  process.exitCode = 1;
}

